import { createHash } from 'node:crypto';
import dns from 'node:dns/promises';
import net from 'node:net';

export interface McpToolDefinition {
  name: string;
  description?: string;
  inputSchema: Record<string, unknown>;
}

// 1. Tinh SHA-256 bat bien cho danh sach tools/list de chan Rug Pull (CVE-2025-54136)
export function computeToolsSchemaHash(tools: McpToolDefinition[]): string {
  const normalized = [...tools]
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((t) => ({
      name: t.name,
      description: (t.description || '').trim(),
      inputSchema: t.inputSchema,
    }));
  return createHash('sha256').update(JSON.stringify(normalized)).digest('hex');
}

// Phat hien Injection an trong description va khoa thay doi schema sau duyet
const SUSPICIOUS_INJECTION_RE = /(ignore previous|<IMPORTANT>|\.env|id_rsa|exfiltrate|curl\s+http)/i;

export function verifyMcpCatalogOrThrow(
  serverId: string,
  tools: McpToolDefinition[],
  lockedSha256: string
): void {
  for (const tool of tools) {
    const desc = tool.description || '';
    if (SUSPICIOUS_INJECTION_RE.test(desc)) {
      throw new Error(`[TOOL_POISON_BLOCKED] ${serverId}:${tool.name} chua dau hieu tiem prompt an!`);
    }
  }
  const actualHash = computeToolsSchemaHash(tools);
  if (actualHash !== lockedSha256) {
    throw new Error(
      `[RUG_PULL_DETECTED] Schema hash lech tai ${serverId}! Expected=${lockedSha256}, Actual=${actualHash}`
    );
  }
}

// 2. Chan SSRF: Giai DNS va tu choi moi dải IP Private/Loopback/Cloud Metadata
function isPrivateOrReservedIp(ip: string): boolean {
  if (net.isIPv4(ip)) {
    const [a, b] = ip.split('.').map(Number);
    if (a === 10 || a === 127 || a === 0) return true;
    if (a === 169 && b === 254) return true; // Cloud metadata 169.254.169.254
    if (a === 172 && b >= 16 && b <= 31) return true;
    if (a === 192 && b === 168) return true;
    if (a === 100 && b >= 64 && b <= 127) return true; // CGNAT
    return false;
  }
  // IPv6 loopback, link-local, unique-local
  const norm = ip.toLowerCase();
  return norm === '::1' || norm.startsWith('fe80:') || norm.startsWith('fc') || norm.startsWith('fd');
}

export async function assertSafeOutboundUrl(rawUrl: string, allowedDomains: Set<string>): Promise<URL> {
  const parsed = new URL(rawUrl);
  if (parsed.protocol !== 'https:') {
    throw new Error('[SSRF_BLOCKED] Chi cho phep giao thuc HTTPS.');
  }
  if (!allowedDomains.has(parsed.hostname)) {
    throw new Error(`[SSRF_BLOCKED] Ten mien ${parsed.hostname} khong nam trong allowlist.`);
  }
  const records = await dns.lookup(parsed.hostname, { all: true });
  for (const rec of records) {
    if (isPrivateOrReservedIp(rec.address)) {
      throw new Error(`[SSRF_BLOCKED] Phat hien phan giai ve IP noi bo ${rec.address}`);
    }
  }
  return parsed;
}

